// Extrair dados da mensagem do WhatsApp
const body = $input.first().json.body;

try {
  const entry = body?.entry?.[0];
  const change = entry?.changes?.[0]?.value;
  const messages = change?.messages;

  // Ignorar status updates (delivered, read, etc)
  if (!messages || messages.length === 0) {
    return [{ json: { ignorar: true } }];
  }

  const msg = messages[0];

  // Ignorar mensagens que não são texto
  if (msg.type !== 'text') {
    return [{ json: { ignorar: true, motivo: 'tipo não suportado: ' + msg.type } }];
  }

  const contact = change?.contacts?.[0];

  return [{
    json: {
      ignorar: false,
      phone: msg.from,
      name: contact?.profile?.name || 'Cliente',
      message: msg.text.body,
      message_id: msg.id,
      phone_number_id: change?.metadata?.phone_number_id,
      timestamp: msg.timestamp
    }
  }];
} catch (e) {
  return [{ json: { ignorar: true, erro: e.message } }];
}

// Montar o array de mensagens para a API do Groq
const dadosMensagem = $('📋 Extrair Dados da Mensagem').first().json;
const historico = $('🗂️ Buscar Histórico (Supabase)').all().map(i => i.json);

// System prompt com dados do produto
const systemPrompt = `Você é a Ana, assistente virtual da Elite Atacado Brasil.

SOBRE O PRODUTO:
A Elite Atacado Brasil é uma plataforma digital com 165 fornecedores atacadistas verificados dos maiores polos do Brasil: Brás (SP), Rua 44 (Goiânia), Caruaru (PE), Nova Serrana (MG) e 25 de Março (SP). Além do diretório, oferece treinamentos, calculadora de lucro, checklist de excursão e prompts de IA.

PREÇO E ACESSO:
- Valor: R$ 97,37 (pagamento único, sem mensalidade)
- Acesso vitalício com atualizações
- Link de compra: ${$env.HOTMART_LINK}
- Acesso liberado em até 5 minutos após compra

REGRAS:
1. Responda sempre em português brasileiro informal e simpático
2. Seja concisa — máximo 3 parágrafos
3. Nunca invente informações
4. Sempre inclua o link quando perguntarem sobre preço
5. Use no máximo 2 emojis por mensagem
6. Se não souber responder algo específico, diga: "Essa dúvida nossa equipe resolve! Me conta mais detalhes."`;

const messages = [{ role: 'system', content: systemPrompt }];

// Adicionar histórico (reverso para ordem cronológica)
const historicoOrdenado = [...historico].reverse().slice(-8);
for (const msg of historicoOrdenado) {
  messages.push({
    role: msg.de_quem === 'cliente' ? 'user' : 'assistant',
    content: msg.mensagem
  });
}

// Adicionar mensagem atual
messages.push({ role: 'user', content: dadosMensagem.message });

return [{
  json: {
    messages,
    phone: dadosMensagem.phone,
    name: dadosMensagem.name,
    phone_number_id: dadosMensagem.phone_number_id,
    mensagem_cliente: dadosMensagem.message
  }
}];

const groqData = $input.first().json;
const promptData = $('🧠 Montar Prompt com Histórico').first().json;

const resposta = groqData.choices?.[0]?.message?.content || 'Olá! Tive um problema técnico. Pode repetir sua mensagem?';

return [{
  json: {
    resposta,
    phone: promptData.phone,
    name: promptData.name,
    phone_number_id: promptData.phone_number_id,
    mensagem_cliente: promptData.mensagem_cliente
  }
}];
